_LOGO_CSS_TEMPLATE = """
<style>
.dn-brand-mark {
    width: 50px;
    height: 50px;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    background-image: url("data:image/webp;base64,__MARK_DATA__");
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    font-size: 0;
    color: transparent;
    filter: drop-shadow(0 8px 20px rgba(91, 157, 255, 0.35));
}
.dn-brand { gap: 14px; }
.dn-lockup {
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 2px 0 16px 0;
}
.dn-lockup img {
    height: 116px;
    width: auto;
    filter: drop-shadow(0 22px 48px rgba(0, 0, 0, 0.55));
}
@media (max-width: 700px) {
    .dn-lockup img { height: 86px; }
}
</style>
"""


def _page_icon():
    """Tarayici sekmesi ikonu logo olur; olmazsa emojiye duser."""
    try:
        import base64 as _b64
        import io as _io

        from PIL import Image

        img = Image.open(_io.BytesIO(_b64.b64decode(_LOGO_MARK_B64)))
        img.load()
        return img
    except Exception:  # noqa: BLE001 - ikon kritik degil
        return "\U0001F697"


def _inject_logo() -> None:
    """Tema CSS'inden sonra logoyu devreye alir."""
    st.markdown(
        _LOGO_CSS_TEMPLATE.replace("__MARK_DATA__", _LOGO_MARK_B64),
        unsafe_allow_html=True,
    )


def _brand_header() -> None:
    """Giris ekraninin ustundeki buyuk logo."""
    st.markdown(
        '<div class="dn-lockup">'
        f'<img src="data:image/webp;base64,{_LOGO_LOCKUP_B64}" '
        'alt="DriveNow Premium" /></div>',
        unsafe_allow_html=True,
    )


from drivenow import db
from drivenow.components import esc, initials
from drivenow.config import APP_NAME, APP_SUFFIX, DEMO_MODE
from drivenow.state import (
    current_user,
    init_state,
    is_guest,
    logout,
    session_expired,
    set_flash,
    show_flash,
    touch_session,
)
from drivenow.theme import inject_theme
from drivenow.views import account, admin, auth, booking, fleet

st.set_page_config(
    page_title=f"{APP_NAME} {APP_SUFFIX} • Araç Kiralama",
    page_icon=_page_icon(),
    layout="wide",
    initial_sidebar_state="collapsed",
    menu_items={
        "Get help": None,
        "Report a bug": None,
        "About": f"{APP_NAME} {APP_SUFFIX} — premium araç kiralama deneyimi.",
    },
)


def _bootstrap() -> None:
    # Bilinçli olarak önbelleğe alınmaz: veritabanı dosyası silinir, taşınır
    # veya bozulursa şema her çalıştırmada yeniden kurulabilsin.
    db.init_db()


try:
    _bootstrap()
except Exception as exc:  # noqa: BLE001 - kullanıcıya anlaşılır mesaj göster
    st.error(
        "Veritabanı başlatılamadı. Sayfayı yenileyin; sorun sürerse yönetici "
        f"ile iletişime geçin. Ayrıntı: {type(exc).__name__}: {exc}"
    )
    st.stop()

inject_theme()
_inject_logo()
init_state()

# --- Oturum süresi ----------------------------------------------------------
if (
    st.session_state.get("auth")
    and not is_guest()
    and session_expired()
):
    logout()
    set_flash("Oturum süreniz doldu. Güvenliğiniz için tekrar giriş yapın.", "warning")
    st.rerun()
touch_session()


def _topbar() -> None:
    user = current_user() or {}
    guest = is_guest()
    left, right = st.columns([3, 1.15], vertical_alignment="center")

    with left:
        st.markdown(
            '<div class="dn-topbar" style="padding-bottom:6px">'
            '<div class="dn-brand">'
            '<div class="dn-brand-mark"></div>'
            "<div>"
            f'<div class="dn-brand-name">{esc(APP_NAME)} <span>{esc(APP_SUFFIX)}</span></div>'
            '<div class="dn-brand-sub">Premium Araç Kiralama</div>'
            "</div></div></div>",
            unsafe_allow_html=True,
        )

    with right:
        if st.session_state.get("auth") and not guest:
            chip, action = st.columns([2.1, 1], vertical_alignment="center")
            with chip:
                st.markdown(
                    '<div class="dn-user-chip">'
                    f'<div class="dn-avatar">{esc(initials(user.get("ad", "")))}</div>'
                    "<div>"
                    f'<b>{esc(user.get("ad", "Müşteri"))}</b>'
                    f'<small>{esc(user.get("email", "") or "Doğrulanmış üye")}</small>'
                    "</div></div>",
                    unsafe_allow_html=True,
                )
            with action:
                if st.button("Çıkış", width="stretch", key="topbar_logout"):
                    logout()
                    set_flash("Güvenli çıkış yapıldı. Tekrar bekleriz.", "info")
                    st.rerun()
        elif guest:
            chip, action = st.columns([2.1, 1], vertical_alignment="center")
            with chip:
                st.markdown(
                    '<div class="dn-user-chip">'
                    '<div class="dn-avatar">👤</div>'
                    "<div><b>Misafir</b><small>Keşif modu</small></div></div>",
                    unsafe_allow_html=True,
                )
            with action:
                if st.button("Giriş yap", width="stretch", key="topbar_login"):
                    st.session_state["auth"] = False
                    st.session_state["guest"] = False
                    st.session_state["user"] = None
                    st.rerun()


def _login_prompt(title: str, text: str) -> None:
    st.markdown(
        f'<div class="dn-empty"><div class="dn-empty__icon">🔐</div>'
        f"<b>{esc(title)}</b><span>{esc(text)}</span></div>",
        unsafe_allow_html=True,
    )
    c1, c2, c3 = st.columns([1, 1, 1])
    with c2:
        if st.button("Giriş ekranına dön", type="primary", width="stretch"):
            st.session_state["auth"] = False
            st.session_state["guest"] = False
            st.session_state["user"] = None
            st.session_state["auth_notice"] = "Devam etmek için lütfen giriş yapın."
            st.rerun()


def _footer() -> None:
    demo = " • Demo modu" if DEMO_MODE else ""
    year = date.today().year
    st.markdown(
        '<div class="dn-footer">'
        f"<div><b>{esc(APP_NAME)} {esc(APP_SUFFIX)}</b> • Premium filo, kapınıza teslim{demo}</div>"
        "<div>destek@drivenow.com.tr • 0850 000 00 00 • Konya / Türkiye</div>"
        f"<div>© {year} DriveNow. Tüm hakları saklıdır.</div>"
        "</div>",
        unsafe_allow_html=True,
    )


# --- Giriş yapılmamış -------------------------------------------------------
if not st.session_state.get("auth"):
    _brand_header()
    auth.render()
    _footer()
    st.stop()

_topbar()
show_flash()

booking_active = bool(
    st.session_state.get("secili") or st.session_state.get("show_booking_success")
)

if booking_active:
    booking.render()
    _footer()
    st.stop()

NAV_ICONS = {
    "Filo": "🚗",
    "Rezervasyonlarım": "🧾",
    "Hesabım": "👤",
    "Yönetim": "🛠️",
}
nav = st.segmented_control(
    "Gezinme",
    list(NAV_ICONS.keys()),
    key="nav",
    format_func=lambda item: f"{NAV_ICONS[item]} {item}",
    label_visibility="collapsed",
    width="stretch",
    wrap=True,
)
nav = nav or "Filo"

if nav == "Filo":
    fleet.render()
elif nav == "Rezervasyonlarım":
    if is_guest():
        _login_prompt(
            "Rezervasyonlar için giriş gerekli",
            "Misafir modunda yalnızca filoyu keşfedebilirsiniz.",
        )
    else:
        account.render("reservations")
elif nav == "Hesabım":
    if is_guest():
        _login_prompt(
            "Hesabınıza erişmek için giriş yapın",
            "Profil, favoriler ve geçmiş kiralamalar üyelere özeldir.",
        )
    else:
        account.render()
elif nav == "Yönetim":
    admin.render()

_footer()
